import subprocess, random
from scan import hits, base
ks=set(int((a-base)//205) for a in hits)
print(len(ks), 0 in ks)
D={1:(-2,1),2:(-1,2),3:(1,2),4:(2,1),5:(2,-1),6:(1,-2),7:(-1,-2),8:(-2,-1)}
OFF={d:12*dr+dc for d,(dr,dc) in D.items()}
import sys
sys.setrecursionlimit(10000)
def nbrs(k,vis):
    return [(d,k+o) for d,o in OFF.items() if (k+o) in ks and (k+o) not in vis]
def solve():
    for _ in range(20000):
        vis={0}; k=0; path=[]
        ok=True
        for _s in range(63):
            opts=[]
            for d,n in nbrs(k,vis):
                cnt=len(nbrs(n,vis|{n}))
                opts.append((cnt+random.random(),d,n))
            if not opts: ok=False;break
            _,d,k=min(opts); vis.add(k); path.append(d)
        if ok and len(vis)==64: return ''.join(map(str,path))
    return None
def test(s):
    p=subprocess.run(['./maze_public'],input=(s+'\n').encode(),capture_output=True,timeout=5)
    return p.stdout[-80:]
s=solve(); print(s); print(test(s) if s else None)
